    public static function plannerIndex(): array
    {
        $metadata = app(TemplateMetadataService::class);
        $templates = self::all();
        $diversity = app(TemplateDiversityService::class)->profiles($templates);

        return collect($templates)
            ->map(fn (array $template) => array_merge(
                $metadata->plannerPayload($template),
                $diversity[(string) ($template['key'] ?? '')] ?? []
            ))
            ->values()
            ->all();
    }

    public static function enriched(string $key): ?array
    {
        $template = self::find($key);

        return $template ? app(TemplateMetadataService::class)->enrich($template) : null;
    }

    public static function price(string $key): int
    {
        $template = self::find($key);
        return (int) ($template['price_credits'] ?? self::PURCHASE_CREDITS);
    }

    public static function find(string $key): ?array
    {
        return collect(self::all())->firstWhere('key', $key);
    }
}
